	private static void readSubjectStatementBucket(Path directory, int partition, int partitionCount,
			BulkCompression compression, SubjectStatementVisitor visitor) throws IOException {
		BulkLz4.readConcatenated(SubjectStatementBucketWriter.path(directory, partition), compression,
				input -> readSubjectStatementFrame(input, partition, partitionCount, visitor));
	}

	private static void readSubjectStatementFrame(DataInputStream input, int partition, int partitionCount,
			SubjectStatementVisitor visitor) throws IOException {
		while (true) {
			long ordinal;
			try {
				ordinal = input.readLong();
			} catch (EOFException e) {
				return;
			}
			try {
				long subjectHash = input.readLong();
				byte[] subject = readKey(input);
				long predicateHash = input.readLong();
				byte[] predicate = readKey(input);
				long objectHash = input.readLong();
				byte[] object = readKey(input);
				long contextHash = input.readLong();
				byte[] context = readNullableKey(input);
				validateHash(subjectHash, subject, partition, partitionCount);
				validateHash(predicateHash, predicate, -1, partitionCount);
				validateHash(objectHash, object, -1, partitionCount);
				if (context != null) {
					validateHash(contextHash, context, -1, partitionCount);
				}
				visitor.accept(ordinal, subjectHash, subject, predicateHash, predicate, objectHash, object,
						contextHash, context);
			} catch (EOFException e) {
				throw new IOException("Truncated subject-routed statement bucket in partition " + partition, e);
			}
		}
	}

	private static byte[] readKey(DataInputStream input) throws IOException {
		int length = input.readInt();
		if (length < 0 || length > MAX_KEY_BYTES) {
			throw new IOException("Invalid subject-routed statement key length: " + length);
		}
		byte[] key = new byte[length];
		input.readFully(key);
		return key;
	}

	private static byte[] readNullableKey(DataInputStream input) throws IOException {
		int length = input.readInt();
		if (length == -1) {
			return null;
		}
		if (length < 0 || length > MAX_KEY_BYTES) {
			throw new IOException("Invalid subject-routed statement key length: " + length);
		}
		byte[] key = new byte[length];
		input.readFully(key);
		return key;
	}

	private static void validateHash(long routeHash, byte[] key, int expectedPartition, int partitionCount)
			throws IOException {
		if (CanonicalTermCodec.routeHash64(key) != routeHash) {
			throw new IOException("Subject-routed statement route hash mismatch");
		}
		if (expectedPartition >= 0 && ((int) routeHash & (partitionCount - 1)) != expectedPartition) {
			throw new IOException("Subject-routed statement belongs to a different partition");
		}
	}

	private static final class SubjectStatementBucketWriter implements AutoCloseable {

		private final BulkCompression compression;
		private final Path directory;
		private final int partitionCount;
		private final BoundedBucketOutputLimiter outputs;

		private SubjectStatementBucketWriter(BulkCompression compression, Path directory, int partitionCount,
				int maxOpenFiles) {
			this.compression = compression;
			this.directory = directory;
			this.partitionCount = partitionCount;
			outputs = new BoundedBucketOutputLimiter(maxOpenFiles);
		}

		private void write(long ordinal, byte[] subject, byte[] predicate, byte[] object, byte[] context)
				throws IOException {
			long subjectHash = CanonicalTermCodec.routeHash64(subject);
			int partition = (int) subjectHash & (partitionCount - 1);
			DataOutputStream output = outputs.output(partition,
					() -> BulkLz4.appendOutput(path(directory, partition), compression));
			output.writeLong(ordinal);
			writeKey(output, subjectHash, subject);
			writeKey(output, CanonicalTermCodec.routeHash64(predicate), predicate);
			writeKey(output, CanonicalTermCodec.routeHash64(object), object);
			if (context == null) {
				output.writeLong(0L);
				output.writeInt(-1);
			} else {
				writeKey(output, CanonicalTermCodec.routeHash64(context), context);
			}
		}

		private static void writeKey(DataOutputStream output, long routeHash, byte[] key) throws IOException {
			output.writeLong(routeHash);
			output.writeInt(key.length);
			output.write(key);
		}

		@Override
		public void close() throws IOException {
			outputs.close();
		}

		private static Path path(Path directory, int partition) {
			return directory.resolve(String.format(Locale.ROOT, "subject-statements-%05d.lz4", partition));
		}
	}

	private static final class LookupCache {

		private final long[] hashes;
		private final byte[][] keys;
		private final long[] ids;
		private final int mask;

		private LookupCache(int capacity) {
			hashes = new long[capacity];
			keys = new byte[capacity][];
			ids = new long[capacity];
			mask = capacity - 1;
		}

		private long lookup(long hash, byte[] key) {
			int slot = (int) hash & mask;
			return keys[slot] != null && hashes[slot] == hash && Arrays.equals(keys[slot], key) ? ids[slot] : 0L;
		}

		private void put(long hash, byte[] key, long id) {
			if (key.length > 1024) {
				return;
			}
			int slot = (int) hash & mask;
			hashes[slot] = hash;
			keys[slot] = key;
			ids[slot] = id;
		}
	}

